"""ffmpeg wrapper: clips are generated by ffmpeg itself (lavfi), no binary fixtures."""

import os
import shutil
import subprocess

import pytest

from src.studio import ffmpeg
from src.studio.ffmpeg import FFmpegError, FFmpegNotFound, FFmpegTimeout

# Skip locally without ffmpeg; in CI (CI=true) a missing ffmpeg must fail, not skip.
needs_ffmpeg = pytest.mark.skipif(
    not (shutil.which("ffmpeg") and shutil.which("ffprobe")) and not os.environ.get("CI"),
    reason="ffmpeg/ffprobe not on PATH",
)

VIDEO = ["-f", "lavfi", "-i", "testsrc2=size=320x568:rate=30:duration=2"]
TONE = ["-f", "lavfi", "-i", "sine=frequency=440:duration=2"]
H264 = ["-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p"]


@pytest.fixture(autouse=True)
def _no_overrides(monkeypatch):
    monkeypatch.delenv("FFMPEG_PATH", raising=False)
    monkeypatch.delenv("FFPROBE_PATH", raising=False)


@needs_ffmpeg
def test_probe_clip_with_audio(tmp_path):
    out = tmp_path / "clip.mp4"
    log = tmp_path / "ffmpeg.log"
    result = ffmpeg.run([*VIDEO, *TONE, *H264, "-c:a", "aac", "-shortest", out],
                        timeout_s=60, log_path=log)
    assert result.returncode == 0 and result.elapsed > 0
    assert log.read_text(encoding="utf-8").strip()  # full stderr kept

    info = ffmpeg.probe(out)
    assert info.duration == pytest.approx(2.0, abs=0.1)
    assert (info.width, info.height) == (320, 568)
    assert info.fps == pytest.approx(30.0)
    assert info.video_codec == "h264"
    assert info.has_audio and info.audio_codec == "aac"
    assert info.sample_rate == 44100
    assert info.size_bytes == out.stat().st_size > 0


@needs_ffmpeg
def test_probe_video_only(tmp_path):
    out = tmp_path / "silent.mp4"
    ffmpeg.run([*VIDEO, *H264, out], timeout_s=60)
    info = ffmpeg.probe(out)
    assert not info.has_audio
    assert info.audio_codec is None and info.sample_rate is None
    assert info.fps == pytest.approx(30.0)


@needs_ffmpeg
def test_probe_rejects_non_media_and_missing(tmp_path):
    for name in ("notes.txt", "notes.bin"):  # .txt is read by ffprobe's tty demuxer
        text = tmp_path / name
        text.write_text("just some text, not a video\n" * 20)
        with pytest.raises(FFmpegError):
            ffmpeg.probe(text)
    with pytest.raises(FileNotFoundError):
        ffmpeg.probe(tmp_path / "missing.mp4")


@needs_ffmpeg
def test_run_timeout_kills_process(tmp_path, monkeypatch):
    started = []

    class SpyPopen(subprocess.Popen):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            started.append(self)

    monkeypatch.setattr(subprocess, "Popen", SpyPopen)
    log = tmp_path / "timeout.log"
    with pytest.raises(FFmpegTimeout):
        # testsrc2 without a duration never ends.
        ffmpeg.run(["-f", "lavfi", "-i", "testsrc2", "-f", "null", "-"],
                   timeout_s=0.5, log_path=log)
    assert len(started) == 1 and started[0].poll() is not None  # killed and reaped
    assert log.exists()


@needs_ffmpeg
def test_run_bad_args_raises_with_stderr_tail(tmp_path):
    with pytest.raises(FFmpegError) as exc:
        ffmpeg.run(["-i", tmp_path / "nope.mp4", tmp_path / "out.mp4"], timeout_s=30)
    assert exc.value.returncode not in (None, 0)
    assert "nope.mp4" in exc.value.stderr_tail
    assert len(exc.value.stderr_tail.splitlines()) <= ffmpeg.TAIL_LINES
    assert not isinstance(exc.value, FFmpegTimeout)


def test_not_found_when_env_points_nowhere(tmp_path, monkeypatch):
    monkeypatch.setenv("FFMPEG_PATH", str(tmp_path / "no-ffmpeg.exe"))
    monkeypatch.setenv("FFPROBE_PATH", str(tmp_path / "no-ffprobe.exe"))
    with pytest.raises(FFmpegNotFound, match="FFMPEG_PATH"):
        ffmpeg.find_ffmpeg()
    with pytest.raises(FFmpegNotFound, match="FFPROBE_PATH"):
        ffmpeg.find_ffprobe()
    with pytest.raises(FFmpegNotFound):
        ffmpeg.run(["-version"], timeout_s=5)


def test_not_found_on_path_gives_install_hint(monkeypatch):
    monkeypatch.setattr(ffmpeg.shutil, "which", lambda name: None)
    with pytest.raises(FFmpegNotFound, match=ffmpeg.install_hint().split()[0]):
        ffmpeg.find_ffmpeg()
